package mcpserver

// Endpoint contracts are implemented directly; see docs/api-coverage.md.
func Endpoints() []Endpoint {
	return []Endpoint{
		{Name: "get_blog", Description: "Read a blog profile by its URL slug.", Method: "GET", Path: "/v1/blog/{blog}"},
		{Name: "list_posts", Description: "Read one page of posts, including access flags and pagination.", Method: "GET", Path: "/v1/blog/{blog}/post/", Query: "limit offset comments_limit reply_limit from_ts to_ts level_id tags_ids", Defaults: map[string]any{"limit": 20}},
		{Name: "get_post", Description: "Read one post with its original content blocks.", Method: "GET", Path: "/v1/blog/{blog}/post/{post_id}", Query: "comments_limit reply_limit"},
		{Name: "create_post", Description: "Create a blog post. Set price and publish_time explicitly as needed.", Method: "POST", Path: "/v1/blog/{blog}/post/", Form: "title data price teaser_data tags deny_comments wait_video publish_time advertiser_info has_chat", Auth: true, Write: true, Experimental: true, Defaults: map[string]any{"data": []any{}, "teaser_data": []any{}}},
		{Name: "update_post", Description: "Update only supplied post fields. Omitted content and teaser are preserved.", Method: "PUT", Path: "/v1/blog/{blog}/post/{post_id}", Form: "title data price teaser_data tags deny_comments wait_video publish_time advertiser_info", Auth: true, Write: true, Experimental: true},
		{Name: "delete_post", Description: "Permanently delete a blog post.", Method: "DELETE", Path: "/v1/blog/{blog}/post/{post_id}", Auth: true, Write: true, Experimental: true},
		{Name: "get_post_deferred_access", Description: "Read scheduled changes to a post access level.", Method: "GET", Path: "/v1/blog/{blog}/post/{post_id}/deferred_access", Auth: true},
		{Name: "update_post_deferred_access", Description: "Set scheduled price and comment access changes.", Method: "PUT", Path: "/v1/blog/{blog}/post/{post_id}/deferred_access", Form: "isCommentsDenied! price! applyTime!", Auth: true, Write: true, Experimental: true, JSON: true},
		{Name: "list_subscription_levels", Description: "List a blog subscription levels.", Method: "GET", Path: "/v1/blog/{blog}/subscription_level/", Query: "show_free_level"},
		{Name: "get_subscription_level", Description: "Read one subscription level.", Method: "GET", Path: "/v1/blog/{blog}/subscription/level/{level}", Query: "with_content_counters"},
		{Name: "list_subscribers", Description: "List subscribers of your own blog.", Method: "GET", Path: "/v1/blog/{blog}/subscribers", Query: "limit offset sort_by order with_follow", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "list_blacklist", Description: "Read the blog blacklist. blog_url is the blog slug.", Method: "GET", Path: "/v1/blacklist/", Query: "blog_url!", Auth: true},
		{Name: "list_unsubscribe_reasons", Description: "List unsubscribe survey responses for your blog.", Method: "GET", Path: "/v1/blog/{blog}/unsubscribe_reasons/", Query: "limit offset sort_by order level_ids answers from to", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "list_media", Description: "List blog media with type all, image, video, or audio.", Method: "GET", Path: "/v1/blog/{blog}/media_album/", Query: "limit offset type", Defaults: map[string]any{"type": "all", "limit": 20}},
		{Name: "get_feed", Description: "Read one page of the personal feed, including blogs and counters.", Method: "GET", Path: "/v1/feed/post/", Query: "limit offset only_allowed", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "search_blogs", Description: "Search blogs.", Method: "GET", Path: "/v1/search/blog/", Query: "search_query! limit offset ", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "suggest_blogs", Description: "Suggest blogs by partial name.", Method: "GET", Path: "/v1/search/blog/suggest/", Query: "search_query! limit offset ", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "search_feed_tags", Description: "Search tags in your feed.", Method: "GET", Path: "/v1/search/feed/tag/", Query: "search_query! limit offset ", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "search_feed_posts", Description: "Search your feed posts.", Method: "GET", Path: "/v1/search/feed/post/", Query: "search_query! limit offset only_allowed only_bought from_ts to_ts tags_ids", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "search_blog_posts", Description: "Search posts in a blog; blog_url is the slug.", Method: "GET", Path: "/v1/search/blog/post/", Query: "search_query! limit offset blog_url! only_allowed subscription_level has_image has_audio_file has_audio has_ok_video has_video has_file from_ts to_ts", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "list_comments", Description: "Read one page of post comments.", Method: "GET", Path: "/v1/blog/{blog}/post/{post_id}/comment/", Query: "limit offset reply_limit order", Defaults: map[string]any{"limit": 20}},
		{Name: "list_comment_replies", Description: "Read replies using the parent comment numeric intId.", Method: "GET", Path: "/v1/blog/{blog}/post/{post_id}/comment/", Query: "parent_id! limit offset order", Defaults: map[string]any{"limit": 20}},
		{Name: "create_comment", Description: "Publish a comment or reply using Boosty content blocks.", Method: "POST", Path: "/v1/blog/{blog}/post/{post_id}/comment/", Form: "data! reply_to_id reply_id", Auth: true, Write: true, Experimental: true},
		{Name: "react_to_post", Description: "Set your reaction on a post.", Method: "POST", Path: "/v1/blog/{blog}/post/{post_id}/reaction", Query: "from_page", Form: "reaction!", Auth: true, Write: true, Experimental: true},
		{Name: "remove_post_reaction", Description: "Remove your reaction from a post.", Method: "DELETE", Path: "/v1/blog/{blog}/post/{post_id}/reaction", Query: "from_page", Auth: true, Write: true, Experimental: true},
		{Name: "like_post", Description: "Like a post.", Method: "POST", Path: "/v1/blog/{blog}/post/{post_id}/like", Query: "from_page", Auth: true, Write: true, Experimental: true},
		{Name: "unlike_post", Description: "Remove your like from a post.", Method: "DELETE", Path: "/v1/blog/{blog}/post/{post_id}/like", Query: "from_page", Auth: true, Write: true, Experimental: true},
		{Name: "react_to_comment", Description: "Set your reaction on a comment.", Method: "POST", Path: "/v1/blog/{blog}/post/{post_id}/comment/{comment_id}/reaction", Query: "from_page", Form: "reaction!", Auth: true, Write: true, Experimental: true},
		{Name: "remove_comment_reaction", Description: "Remove your reaction from a comment.", Method: "DELETE", Path: "/v1/blog/{blog}/post/{post_id}/comment/{comment_id}/reaction", Query: "from_page", Auth: true, Write: true, Experimental: true},
		{Name: "like_comment", Description: "Like a comment.", Method: "POST", Path: "/v1/blog/{blog}/post/{post_id}/comment/{comment_id}/reaction", Query: "from_page", Auth: true, Write: true, Experimental: true},
		{Name: "unlike_comment", Description: "Remove your like from a comment.", Method: "DELETE", Path: "/v1/blog/{blog}/post/{post_id}/comment/{comment_id}/reaction", Query: "from_page", Auth: true, Write: true, Experimental: true},
		{Name: "get_poll", Description: "Read a blog poll.", Method: "GET", Path: "/v1/blog/{blog}/poll/{poll_id}", Query: "voters_limit", Experimental: true},
		{Name: "list_poll_voters", Description: "List voters for a poll option.", Method: "GET", Path: "/v1/blog/{blog}/poll/{poll_id}/vote/", Query: "limit offset option", Auth: true, Experimental: true, Defaults: map[string]any{"limit": 20}},
		{Name: "vote_poll", Description: "Replace your entire poll vote with comma-separated option IDs in answer.", Method: "POST", Path: "/v1/poll/{poll_id}/vote", Form: "answer! other is_anonymous", Auth: true, Write: true, Experimental: true},
		{Name: "unvote_poll", Description: "Withdraw your entire poll vote.", Method: "DELETE", Path: "/v1/poll/{poll_id}/vote", Auth: true, Write: true, Experimental: true},
		{Name: "get_current_user", Description: "Read the connected account.", Method: "GET", Path: "/v1/user/current", Auth: true},
		{Name: "list_subscriptions", Description: "List your subscriptions and optionally follows.", Method: "GET", Path: "/v1/user/subscriptions", Query: "limit offset with_follow", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "list_sessions", Description: "Read your active sessions, including device and IP information.", Method: "GET", Path: "/v1/user/session/", Auth: true},
		{Name: "get_notification_settings", Description: "Read notification settings by comma-separated transport names.", Method: "GET", Path: "/v1/notification/settings/", Query: "transports", Auth: true, Defaults: map[string]any{"transports": "standalone,mobile_push,telegram,mail"}},
		{Name: "list_payment_cards", Description: "Read saved payment card metadata.", Method: "GET", Path: "/v1/payment/bind/list", Query: "currency deleted", Auth: true},
		{Name: "list_blog_currencies", Description: "List available blog currencies.", Method: "GET", Path: "/v1/user/current/blog_currency/available/", Auth: true},
		{Name: "update_profile", Description: "Update only supplied account profile fields.", Method: "PUT", Path: "/v1/user/current", Form: "name email can_view_adult_content send_msg_rule send_msg_level_id", Auth: true, Write: true, Experimental: true},
		{Name: "update_notification_setting", Description: "Set one notification switch.", Method: "PUT", Path: "/v1/notification/settings/{transport}/{switch}", Form: "value!", Auth: true, Write: true, Experimental: true},
		{Name: "update_dialog_settings", Description: "Replace dialog permissions. All six permission switches are required to avoid resetting omitted settings.", Method: "POST", Path: "/v1/user/dialog_settings", Form: "can_send_all! can_send_donation! can_send_my_authors! can_send_paid_subscribers! can_send_subscribers! can_send_payers! send_msg_level_id", Auth: true, Write: true, Experimental: true},
		{Name: "set_locale", Description: "Set your interface language, for example en or ru.", Method: "POST", Path: "/v1/user/locale", Form: "lang!", Auth: true, Write: true, Experimental: true},
		{Name: "end_sessions", Description: "End ALL account sessions, possibly including this MCP login; you may need to log in again.", Method: "DELETE", Path: "/v1/user/session/", Form: "including_current!", Auth: true, Write: true, Experimental: true},
		{Name: "list_dialogs", Description: "Read one page of conversations.", Method: "GET", Path: "/v1/dialog/", Query: "limit offset", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "get_dialog_with_user", Description: "Check an existing conversation and relation.canWrite before creating a dialog.", Method: "GET", Path: "/v1/dialog", Query: "user_id!", Auth: true},
		{Name: "create_dialog", Description: "Create a conversation with a user. Check relation.canWrite first.", Method: "POST", Path: "/v1/dialog/", Form: "user_id!", Auth: true, Write: true},
		{Name: "list_messages", Description: "Read one page of messages in a conversation.", Method: "GET", Path: "/v1/dialog/{dialog_id}/message/", Query: "limit offset", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "send_message", Description: "Send content blocks to an existing conversation.", Method: "POST", Path: "/v1/dialog/{dialog_id}/message", Form: "data!", Auth: true, Write: true},
		{Name: "list_notifications", Description: "Read your notifications and counters. This endpoint has no pagination.", Method: "GET", Path: "/v1/notification/standalone/event/", Auth: true},
		{Name: "mark_notifications_read", Description: "Mark comma-separated numeric event IDs as read.", Method: "PUT", Path: "/v1/notification/standalone/read/", Form: "event_id!", Auth: true, Write: true},
		{Name: "delete_notification", Description: "Delete a notification.", Method: "DELETE", Path: "/v1/notification/standalone/event/{event}", Auth: true, Write: true, Experimental: true},
		{Name: "delete_notifications", Description: "Delete comma-separated numeric event IDs.", Method: "DELETE", Path: "/v1/notification/standalone/event/", Form: "event_id!", Auth: true, Write: true, Experimental: true},
		{Name: "list_targets", Description: "List a blog fundraising or subscriber targets.", Method: "GET", Path: "/v1/target/{blog}/", Query: "type show_deleted"},
		{Name: "get_target", Description: "Read one target.", Method: "GET", Path: "/v1/target/{target_id}", Query: "currency"},
		{Name: "create_target", Description: "Create a money or subscribers target; blog_url is the blog slug.", Method: "POST", Path: "/v1/target/{target_type}", Form: "blog_url! description! target_sum!", Auth: true, Write: true, Experimental: true},
		{Name: "update_target", Description: "Replace target description and sum; both fields are required.", Method: "PUT", Path: "/v1/target/{target_id}", Form: "description! target_sum!", Auth: true, Write: true, Experimental: true},
		{Name: "delete_target", Description: "Delete a target.", Method: "DELETE", Path: "/v1/target/{target_id}", Auth: true, Write: true, Experimental: true},
		{Name: "list_post_sales", Description: "Read paid post sales.", Method: "GET", Path: "/v1/blog/{blog}/sales/post/", Query: "limit offset sort_by order post_ids", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "list_donations", Description: "Read donations, including donor details.", Method: "GET", Path: "/v1/blog/{blog}/sales/donation/", Query: "limit offset sort_by order type target_id", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "list_bundle_sales", Description: "Read paid bundle sales.", Method: "GET", Path: "/v1/blog/{blog}/sales/bundle/", Query: "limit offset sort_by order bundle_ids", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "list_holds", Description: "Read held payments.", Method: "GET", Path: "/v1/blog/{blog}/sales/hold/", Query: "limit offset", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "list_broadcast_sales", Description: "Read paid broadcast message statistics.", Method: "GET", Path: "/v1/blog/{blog}/sales/dialog_broadcast_message/", Query: "limit offset", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "get_paid_sales_by_date", Description: "Read paid post or bundle sales within a time range.", Method: "GET", Path: "/v1/blog/{blog}/{sale_kind}/paid/by_date", Query: "from! to!", Auth: true},
		{Name: "get_paid_sales_days", Description: "Read days with sales in the month containing date.", Method: "GET", Path: "/v1/blog/{blog}/{sale_kind}/paid/days", Query: "date!", Auth: true},
		{Name: "list_payout_methods", Description: "Read available payout methods.", Method: "GET", Path: "/v1/payout/methods", Auth: true},
		{Name: "list_payouts", Description: "Read your payout destinations, including private payment details.", Method: "GET", Path: "/v1/blog/{blog}/payout/", Auth: true},
		{Name: "list_payout_history", Description: "Read payout history.", Method: "GET", Path: "/v1/blog/{blog}/payout/history/", Query: "limit offset", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "get_default_currency", Description: "Read the default guest currency; always called anonymously.", Method: "GET", Path: "/v1/payment/default_currency", Anonymous: true},
		{Name: "get_stats_summary", Description: "Read your blog balance, income and follower totals.", Method: "GET", Path: "/v1/blog/stat/{blog}/current", Auth: true},
		{Name: "get_stats_metrics", Description: "Read your blog metrics for a time range.", Method: "GET", Path: "/v1/blog/stat/{blog}/metrics", Query: "from! to!", Auth: true},
		{Name: "get_stats_charts", Description: "Read daily metric series.", Method: "GET", Path: "/v1/blog/{blog}/stat/data", Query: "last_time limit", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "list_stats_events", Description: "Read account events; may contain subscriber email addresses.", Method: "GET", Path: "/v1/blog/stat/{blog}/events", Query: "limit offset from to event_types user_ids", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "list_visit_sources", Description: "Read traffic sources grouped by referer or utm.", Method: "GET", Path: "/v1/blog/stat/{blog}/visits", Query: "type! period! limit offset sort_by order timestamp", Auth: true, Defaults: map[string]any{"order": "gt", "limit": 20}},
		{Name: "list_payment_sources", Description: "Read payment sources grouped by referer or utm.", Method: "GET", Path: "/v1/blog/stat/{blog}/payments/analytics", Query: "type! period! limit offset sort_by order timestamp", Auth: true, Defaults: map[string]any{"order": "gt", "limit": 20}},
		{Name: "get_referral_stats", Description: "Read referral totals.", Method: "GET", Path: "/v1/blog/referral/{blog}/stat/", Auth: true},
		{Name: "list_referral_users", Description: "Read referred users.", Method: "GET", Path: "/v1/blog/referral/{blog}/user/", Query: "limit offset only_bloggers", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "search_subscribers", Description: "Search your subscribers; chunk must contain at least three characters.", Method: "GET", Path: "/v1/blog/stat/{blog}/search", Query: "chunk! limit", Auth: true, Defaults: map[string]any{"limit": 20}},
		{Name: "get_post_stats", Description: "Read creator statistics for one post.", Method: "GET", Path: "/v1/blog/stat/{blog}/post/{post_id}", Auth: true, Experimental: true},
		{Name: "get_report_info", Description: "Read the last generated report descriptor.", Method: "GET", Path: "/v1/blog/stat/{blog}/csv/{report_type}/info", Auth: true},
		{Name: "build_report", Description: "Generate a new CSV report and return its download descriptor. This GET has a server-side effect.", Method: "GET", Path: "/v1/blog/stat/{blog}/csv/{report_type}", Query: "separator from to period", Auth: true, Write: true},
	}
}
